/* Questionnaire views share the existing nodes and executable branch graph. */
let questionnaireView='flow';
const questionnaireTypes=['Text','Number','Yes / No','Single choice','Multiple choice','Date','Photo','Video','Catalogue'];
const questionOldInsertMenu=canvasInsertMenu;
canvasInsertMenu=function(id,key){const n=sop().nodes.find(n=>n.id===id);if(!n)return;modal('Insert a question or step',`<p>After ${esc(n.label)}. The next connection is preserved.</p><span class="label">Question types</span><div class="question-type-grid">${questionnaireTypes.map(t=>`<button onclick="insertTypedQuestion('${id}','${key}','${t}')">${esc(t)}</button>`).join('')}</div><span class="label" style="margin-top:20px">Workflow steps</span><div class="actions"><button onclick="canvasInsert('${id}','${key}','condition')">◇ Decision</button><button onclick="canvasInsert('${id}','${key}','action')">↳ Action</button></div><p class="muted" style="margin-top:16px">Catalogue uses a configured shared dropdown source. Photo and video use the local operator preview.</p>`)};
function insertTypedQuestion(id,key,type){if(!canEdit()||!questionnaireTypes.includes(type))return;const existingIds=new Set(sop().nodes.map(n=>n.id));canvasInsert(id,key,'question');const n=sop().nodes.find(n=>n.id===selected);if(!n||existingIds.has(n.id))return;n.answer=type;n.required=true;n.hint='';n.label=type==='Yes / No'?'New yes / no question':type==='Catalogue'?'Select an item':type==='Photo'?'Add photo evidence':type==='Video'?'Add video evidence':'New '+type.toLowerCase()+' question';if(type==='Number'){n.unit='kg';n.min=0;n.max=100}if(['Single choice','Multiple choice'].includes(type))n.choices='Option 1, Option 2';persist();drawGraph();inspect()}
const questionOldInspect=inspect;
inspect=function(){questionOldInspect();const n=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!n||!p||n.type!=='question')return;const dis=!canEdit()?'disabled':'';if(n.answer==='Number')for(const [key,label] of [['min','Minimum answer'],['max','Maximum answer']]){const el=p.querySelector('[aria-label="'+label+'"]');if(el&&n[key]===null){el.value='';el.placeholder='Not specified';el.onchange=()=>editNode(key,el.value===''?null:Number(el.value))}}p.querySelectorAll('p').forEach(el=>{if(el.textContent.startsWith('Required question.'))el.remove()});p.insertAdjacentHTML('beforeend',`<section class="question-settings"><h3>Question settings</h3><label class="checkrow"><input aria-label="Required question" type="checkbox" ${n.required!==false?'checked':''} onchange="editQuestionSetting('required',this.checked)" ${dis}>Required answer</label><label class="field"><span>Operator hint</span><textarea aria-label="Operator hint" oninput="editQuestionSetting('hint',this.value)" ${dis}>${esc(n.hint||'')}</textarea></label>${['Number','Yes / No','Single choice','Multiple choice'].includes(n.answer)?`<h3>Answer paths</h3><p class="muted">${n.answer==='Number'?'Start with an above-minimum decision. Edit its comparator and threshold on the decision step.':n.answer==='Multiple choice'?'First matching choice wins, in displayed choice order. Otherwise uses the default path.':'Each answer follows its own path. Otherwise handles skipped or unmatched answers.'}</p><button onclick="generateQuestionBranches('${n.id}')" ${dis}>${n.generatedBranches?'Update':'Create'} answer branches</button>${n.generatedBranches?'<p class="muted">Generated decision steps are editable in the flow. Existing answer destinations are retained.</p>':''}`:''}</section>`)};
function editQuestionSetting(key,value){if(!canEdit())return;const n=sop().nodes.find(n=>n.id===selected);if(!n)return;const before=JSON.stringify(sop().nodes);n[key]=value;persist();canvasRemember(before);drawGraph()}
function questionChoices(q){if(q.answer==='Number'){const existing=sop().nodes.filter(n=>n.generatedFor===q.id);return existing.length?existing.map(n=>n.value):[String(q.min??0)]}return q.answer==='Yes / No'?['Yes','No']:(q.choices||'').split(',').map(v=>v.trim()).filter(Boolean)}
function generateQuestionBranches(id){if(!canEdit())return;const q=sop().nodes.find(n=>n.id===id);if(!q||!['Number','Yes / No','Single choice','Multiple choice'].includes(q.answer))return;const values=questionChoices(q);if(!values.length||new Set(values).size!==values.length)return toast('Add unique, non-empty choices first.');const existing=sop().nodes.filter(n=>n.generatedFor===id),existingValues=existing.map(n=>n.value),removed=existingValues.filter(v=>!values.includes(v));if(removed.length){modal('Review removed answer paths',`<p>These previously generated answers are no longer in the question: ${removed.map(esc).join(', ')}.</p><p>Their destination steps will remain in the draft for review. They may become disconnected and validation will identify them.</p><button class="primary" onclick="buildQuestionBranches('${id}')">Update paths and retain destination steps</button>`);return}buildQuestionBranches(id)}
function buildQuestionBranches(id){if(!canEdit())return;const nodes=sop().nodes,q=nodes.find(n=>n.id===id);if(!q)return;const before=JSON.stringify(nodes),values=questionChoices(q),old=nodes.filter(n=>n.generatedFor===id),fallback=q.generatedFallback||q.next||nodes.find(n=>n.type==='end')?.id||'',oldIds=new Set(old.map(n=>n.id));q.generatedFallback=fallback;const created=values.map((value,index)=>{const prior=old.find(n=>n.value===value);return prior?{...prior}:{id:'branch-'+crypto.randomUUID(),type:'condition',label:q.label+' · '+value,source:id,op:q.answer==='Number'?'>':q.answer==='Multiple choice'?'contains':'=',value,yes:fallback,no:'',x:q.x+(index%2)*300,y:q.y+190+index*170,generatedFor:id}});created.forEach((n,index)=>{n.source=id;n.no=created[index+1]?.id||fallback});for(const n of nodes)if(n.id!==id&&!oldIds.has(n.id))for(const port of canvasPorts(n))if(oldIds.has(n[port.key])){const oldNode=old.find(x=>x.id===n[port.key]);n[port.key]=created.find(x=>x.value===oldNode.value)?.id||fallback}sop().nodes=nodes.filter(n=>!oldIds.has(n.id)).concat(created);q.next=created[0]?.id||fallback;q.generatedBranches=true;selected=id;persist();canvasRemember(before);closeModal();drawGraph();inspect();canvasFit();toast('Answer branches created; connect each matching path to its action.')}
const questionOldSimInput=simInput;
simInput=function(n){if(n.answer==='Number'&&(n.min===null||n.max===null))return `${n.hint?`<p class="question-operator-hint">${esc(n.hint)}</p>`:''}<input id="simvalue" aria-label="Operator answer" type="number" step="any" ${n.min!==null?`min="${n.min}"`:''} ${n.max!==null?`max="${n.max}"`:''}><div class="hint">${esc(n.unit||'Unit unspecified')} · ${n.min===null?'No minimum supplied':'Minimum '+n.min} · ${n.max===null?'No maximum supplied':'Maximum '+n.max}</div>`;return `${n.hint?`<p class="question-operator-hint">${esc(n.hint)}</p>`:''}${n.required===false?'<span class="badge blue">Optional</span>':''}${questionOldSimInput(n)}`};
const questionOldSimAnswer=simAnswer;
simAnswer=function(){const n=sim?.nodes?.find(n=>n.id===sim.id);if(n?.answer==='Number'&&$('#simvalue')?.validity?.badInput){const err=$('#simerror');if(err)err.textContent='Enter a valid number or clear the answer.';return}if(n?.type==='question'&&n.required===false){const el=$('#simvalue'),v=n.answer==='Multiple choice'?[...document.querySelectorAll('.simcheck:checked')].map(x=>x.value):el?.value;if(!v||!v.length){sim.answers[n.id]='';sim.path.push(n.label+': skipped (optional)');sim.id=n.next;renderSim();return}}if(n?.answer==='Number'&&(n.min===null||n.max===null)){const raw=$('#simvalue')?.value,v=Number(raw);if(!raw||!Number.isFinite(v)||(n.min!==null&&v<n.min)||(n.max!==null&&v>n.max)){const err=$('#simerror');if(err)err.textContent='Enter a valid number within the supplied limits.';return}sim.answers[n.id]=v;sim.path.push(n.label+': '+v);sim.id=n.next;renderSim();return}questionOldSimAnswer()};
const questionOldCompare=compare;
compare=function(a,op,b){if(a===''||a===null||a===undefined)return false;return questionOldCompare(a,op,b)};
const questionOldDraw=drawGraph;
drawGraph=function(){if(questionnaireView!=='list')return questionOldDraw();renderQuestionList()};
function renderQuestionList(){const g=$('#graph');if(!g)return;g.className='question-list';g.style.transform='none';g.style.width='100%';g.style.height='auto';const nodes=sop().nodes;g.innerHTML=`<div class="question-list-heading"><h3>Questions & workflow order</h3><span class="muted">Same draft as Flow. Conditions retain their connections.</span></div>${questionnaireOrder(nodes).map((n,index)=>`<article class="question-list-row ${n.id===selected?'selected':''}"><div class="question-list-number">${index+1}</div><div><span class="badge ${n.type==='question'?'blue':n.type==='condition'?'amber':'purple'}">${esc(n.type==='question'?n.answer:n.type)}</span><h3>${esc(n.label)}</h3>${n.type==='question'?`<p>${n.required===false?'Optional':'Required'}${n.unit?' · '+esc(n.unit):''}${n.hint?' · '+esc(n.hint):''}</p>`:''}<div class="question-list-links">${canvasPorts(n).map(p=>`${esc(p.label)} → ${esc(nodes.find(x=>x.id===n[p.key])?.label||'Not connected')}`).join('<br>')}</div></div><div class="actions"><button onclick="selected='${n.id}';drawGraph();inspect()">Edit</button>${n.type!=='end'?`<button onclick="selected='${n.id}';canvasAddAfterSelected()">+ Insert</button>`:''}</div></article>`).join('')}`}
const questionOldEditor=renderEditor;
renderEditor=function(){questionOldEditor();if(!canEdit()||!$('.toolbar'))return;$('.toolbar').insertAdjacentHTML('afterbegin',`<div class="question-view-toggle"><button class="${questionnaireView==='flow'?'active':''}" onclick="setQuestionnaireView('flow')">Flow</button><button class="${questionnaireView==='list'?'active':''}" onclick="setQuestionnaireView('list')">List</button></div>`);$('.canvas').classList.toggle('question-list-canvas',questionnaireView==='list');if(questionnaireView==='list'){renderQuestionList();$('.canvas').onpointerdown=null;$('.canvas').onwheel=null;$('.canvas-help').style.display='none'}};
function setQuestionnaireView(view){questionnaireView=view;renderEditor()}
function questionnaireImport(title,questions){if(!canEdit())return;const old=sop();(state.archivedSops??={})[current]??=[];state.archivedSops[current].push(structuredClone(old));const nodes=[{id:'start',type:'start',label:'Begin '+title,x:200,y:20,next:''}];questions.forEach((q,index)=>nodes.push({id:q.id||'import-'+crypto.randomUUID(),sourceQuestionId:q.id||'',sourcePage:q.page||'',sourceMetadata:structuredClone(q),importUnsupported:q.unsupported||[],type:'question',label:q.label,answer:q.type||'Text',required:q.required!==false,hint:q.hint||'',choices:Array.isArray(q.choices)?q.choices.join(', '):(q.choices||''),unit:q.unit||'',min:q.min??null,max:q.max??null,catalogueSourceId:q.catalogueSourceId||'',x:200,y:180+index*170,next:''}));nodes.push({id:'end',type:'end',label:'Complete '+title,x:200,y:180+questions.length*170});nodes.forEach((n,i)=>{if(n.type!=='end')n.next=nodes[i+1].id});state.sops[current]={title,version:0,published:null,nodes};persist();selected=nodes[1]?.id||'start';go(current,'Editor');toast('Imported a separate questionnaire draft; previous SOP preserved.')}

function questionnaireOrder(nodes){const indegree=new Map(nodes.map(n=>[n.id,0]));for(const n of nodes)for(const p of canvasPorts(n))if(indegree.has(n[p.key]))indegree.set(n[p.key],indegree.get(n[p.key])+1);const queue=nodes.filter(n=>indegree.get(n.id)===0),out=[];while(queue.length){const n=queue.shift();out.push(n);for(const p of canvasPorts(n)){const id=n[p.key];if(indegree.has(id)){indegree.set(id,indegree.get(id)-1);if(indegree.get(id)===0)queue.push(nodes.find(x=>x.id===id))}}}return out.concat(nodes.filter(n=>!out.includes(n)))}
const questionPreviousValidate=validateWorkflow;validateWorkflow=function(s,m=current){const checked=structuredClone(s);for(const n of checked.nodes)if(n.answer==='Number'){if(n.min===null)n.min=Number.MIN_SAFE_INTEGER;if(n.max===null)n.max=Number.MAX_SAFE_INTEGER}return [...questionPreviousValidate(checked,m),...s.nodes.filter(n=>n.importUnsupported?.length).map(n=>n.label+': unsupported imported fields require review: '+n.importUnsupported.join(', '))]};
const questionPreviousRenderSim=renderSim;renderSim=function(){questionPreviousRenderSim();const n=sim?.nodes?.find(n=>n.id===sim.id);if(n?.required===false)document.querySelectorAll('.phone .badge').forEach(b=>{if(b.textContent==='Required question')b.textContent='Optional question'})};
function questionnaireOptions(q){return Array.isArray(q.options)?q.options:(q.choices||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>({value:x,label:x}))}
const previousQuestionChoices=questionChoices;questionChoices=function(q){return ['Single choice','Multiple choice'].includes(q.answer)?questionnaireOptions(q).map(o=>o.value):previousQuestionChoices(q)};
const structuredSimInput=simInput;simInput=function(q){if(['Single choice','Multiple choice'].includes(q.answer)&&Array.isArray(q.options)){const hint=q.hint?`<p class="question-operator-hint">${esc(q.hint)}</p>`:'';return hint+(q.answer==='Single choice'?`<select id="simvalue" aria-label="Operator answer"><option value="">Select answer…</option>${q.options.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</select>`:q.options.map(o=>`<label class="checkrow"><input class="simcheck" type="checkbox" value="${esc(o.value)}">${esc(o.label)}</label>`).join(''))}return structuredSimInput(q)};
const structuredInspect=inspect;inspect=function(){structuredInspect();const q=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!p||!q||!['Single choice','Multiple choice'].includes(q.answer))return;const existing=p.querySelector('[aria-label="Answer choices"]');existing?.closest('.field')?.remove();p.insertAdjacentHTML('beforeend',`<section class="question-option-editor"><h3>Answer choices</h3><p class="muted">Labels appear to operators; stable values are used by conditions.</p>${questionnaireOptions(q).map((o,i)=>`<div class="question-option-row"><input aria-label="Choice ${i+1} label" value="${esc(o.label)}" oninput="editStructuredOption(${i},'label',this.value)" ${canEdit()?'':'disabled'}><input aria-label="Choice ${i+1} value" value="${esc(o.value)}" oninput="editStructuredOption(${i},'value',this.value)" ${canEdit()?'':'disabled'}><button onclick="deleteStructuredOption(${i})" ${canEdit()?'':'disabled'}>×</button></div>`).join('')}<button onclick="addStructuredOption()" ${canEdit()?'':'disabled'}>+ Add choice</button></section>`)};
function editStructuredOption(index,key,value){if(!canEdit())return;const q=sop().nodes.find(n=>n.id===selected);q.options=structuredClone(questionnaireOptions(q));q.options[index][key]=value;persist();drawGraph()}
function addStructuredOption(){if(!canEdit())return;const q=sop().nodes.find(n=>n.id===selected);q.options=structuredClone(questionnaireOptions(q));q.options.push({value:'option-'+(q.options.length+1),label:'New option'});persist();inspect()}
function deleteStructuredOption(index){if(!canEdit())return;const q=sop().nodes.find(n=>n.id===selected);q.options=structuredClone(questionnaireOptions(q));q.options.splice(index,1);persist();inspect();drawGraph()}
const structuredValidate=validateWorkflow;validateWorkflow=function(s,m=current){const normalized=structuredClone(s);for(const n of normalized.nodes)if(Array.isArray(n.options))n.choices=n.options.map((o,i)=>String(i)).join(',');const errors=structuredValidate(normalized,m);for(const n of s.nodes)if(Array.isArray(n.options)){if(!n.options.length||n.options.some(o=>!String(o.value).trim()||!String(o.label).trim())||new Set(n.options.map(o=>o.value)).size!==n.options.length)errors.push(n.label+': choices need unique values and non-empty labels.')}return [...new Set(errors)]};
const questionValidationChoices=validateWorkflow;validateWorkflow=function(s,m=current){const checked=structuredClone(s);for(const q of checked.nodes){if(Array.isArray(q.options)&&['Single choice','Multiple choice'].includes(q.answer))q.answer='Text';if(q.type==='question'&&q.answer==='Number'&&q.unitOptional&&!q.unit)q.unit='unitless'}const errors=questionValidationChoices(checked,m);for(const condition of s.nodes.filter(n=>n.type==='condition')){const q=s.nodes.find(n=>n.id===condition.source);if(Array.isArray(q?.options)&&['=','!=','contains'].includes(condition.op)&&!q.options.some(o=>String(o.value)===String(condition.value)))errors.push(condition.label+': answer choice value is no longer available; review this branch.')}return [...new Set(errors)]};
const previousStructuredEdit=editStructuredOption;editStructuredOption=function(...args){const before=JSON.stringify(sop().nodes);previousStructuredEdit(...args);canvasRemember(before)};
const previousStructuredAdd=addStructuredOption;addStructuredOption=function(...args){const before=JSON.stringify(sop().nodes);previousStructuredAdd(...args);canvasRemember(before)};
const previousStructuredDelete=deleteStructuredOption;deleteStructuredOption=function(...args){const before=JSON.stringify(sop().nodes);previousStructuredDelete(...args);canvasRemember(before)};
const questionBranchLabel=canvasBranchLabel;canvasBranchLabel=function(n){const q=sop().nodes.find(q=>q.id===n.source);if(Array.isArray(q?.options)){const option=q.options.find(o=>String(o.value)===String(n.value));return `${{'=':'Is','!=':'Is not',contains:'Includes'}[n.op]||n.op} ${option?.label||'Unavailable choice'}`}return questionBranchLabel(n)};
const optionalUnitInspect=inspect;inspect=function(){optionalUnitInspect();const q=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(q?.answer==='Number'&&p){const unit=p.querySelector('[aria-label="Unit"]');if(unit){if(!Array.from(unit.options).some(o=>o.value===''))unit.insertAdjacentHTML('afterbegin','<option value="">No unit</option>');if(!Array.from(unit.options).some(o=>o.value==='cm'))unit.insertAdjacentHTML('beforeend','<option>cm</option>');unit.value=q.unit||'';unit.onchange=()=>{q.unitOptional=unit.value==='';editNode('unit',unit.value)}}}};
const choiceListDetails=renderQuestionList;renderQuestionList=function(){choiceListDetails();const ordered=questionnaireOrder(sop().nodes);document.querySelectorAll('.question-list-row').forEach((row,index)=>{const q=ordered[index];if(q?.type!=='question')return;const detail=Array.isArray(q.options)?`${q.options.length} choices: ${q.options.map(o=>o.label).join(' · ')}`:q.answer==='Number'?`Range: ${q.min??'no minimum'} to ${q.max??'no maximum'} ${q.unit||'(no unit)'}`:'';if(detail)row.querySelector('.question-list-links')?.insertAdjacentHTML('beforebegin',`<p class="question-review-detail">${esc(detail)}</p>`)})};
if(!questionnaireTypes.includes('Photo or video'))questionnaireTypes.push('Photo or video');
function questionProofSettings(q){return q.proof?structuredClone(q.proof):{accepts:q.answer==='Photo'?['photo']:q.answer==='Video'?['video']:['photo','video'],maxFiles:1,minFiles:q.required===false?0:1,slot:q.id}}
const proofQuestionInsert=insertTypedQuestion;insertTypedQuestion=function(...args){proofQuestionInsert(...args);const q=sop().nodes.find(n=>n.id===selected);if(q&&['Photo','Video','Photo or video'].includes(q.answer)){q.proof=questionProofSettings(q);persist();inspect()}};
const proofQuestionInspect=inspect;inspect=function(){proofQuestionInspect();const q=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!q||!p||!['Photo','Video','Photo or video'].includes(q.answer))return;const proof=questionProofSettings(q),dis=canEdit()?'':'disabled';p.insertAdjacentHTML('beforeend',`<section class="question-settings"><h3>Proof capture</h3><label class="field"><span>Allowed capture</span><select aria-label="Allowed proof capture" onchange="saveQuestionProofSetting('capture',this.value)" ${dis}><option value="photo" ${proof.accepts.length===1&&proof.accepts[0]==='photo'?'selected':''}>Photo</option><option value="video" ${proof.accepts.length===1&&proof.accepts[0]==='video'?'selected':''}>Video</option><option value="either" ${proof.accepts.length===2?'selected':''}>Photo or video · either accepted</option></select></label><label class="field"><span>Maximum files</span><input aria-label="Maximum proof files" type="number" min="1" step="1" value="${proof.maxFiles}" onchange="saveQuestionProofSetting('maxFiles',this.value)" ${dis}></label><label class="field"><span>Minimum files when answered</span><input aria-label="Minimum proof files" type="number" min="1" step="1" value="${Math.max(1,proof.minFiles||q.proofRequiredMin||1)}" onchange="saveQuestionProofSetting('minFiles',this.value)" ${dis}></label><p class="muted">${q.required===false?'Optional: skip with zero files; if answered, the minimum applies.':'Required: the minimum number of files must be provided.'} Limits apply only to this question.</p></section>`)};
function saveQuestionProofSetting(key,value){if(!canEdit())return;const q=sop().nodes.find(n=>n.id===selected);if(!q)return;const before=JSON.stringify(sop().nodes),p=questionProofSettings(q);if(key==='capture'){if(!['photo','video','either'].includes(value))return toast('Choose photo, video or either.');p.accepts=value==='either'?['photo','video']:[value];q.answer=value==='photo'?'Photo':value==='video'?'Video':'Photo or video'}else{const n=Number(value);if(!Number.isInteger(n)||n<1){toast('Enter a positive whole number of files.');inspect();return}if(key==='maxFiles'&&n<Math.max(1,p.minFiles||q.proofRequiredMin||1)){toast('Maximum cannot be below the minimum.');inspect();return}if(key==='minFiles'&&n>p.maxFiles){toast('Minimum cannot exceed the maximum.');inspect();return}if(key==='minFiles'){q.proofRequiredMin=n;p.minFiles=q.required===false?0:n}else p.maxFiles=n}q.proof=p;persist();canvasRemember(before);drawGraph();inspect()}
const proofRequiredSetting=editQuestionSetting;editQuestionSetting=function(key,value){const q=sop().nodes.find(n=>n.id===selected),before=JSON.stringify(sop().nodes);if(key==='required'&&q&&['Photo','Video','Photo or video'].includes(q.answer)&&canEdit()){const p=questionProofSettings(q);q.proofRequiredMin=Math.max(1,p.minFiles||q.proofRequiredMin||1);q.required=value;p.minFiles=value?q.proofRequiredMin:0;q.proof=p;persist();canvasRemember(before);drawGraph();inspect();return}proofRequiredSetting(key,value)};

const proofSettingsValidate=validateWorkflow;validateWorkflow=function(s,m=current){const errors=proofSettingsValidate(s,m);for(const q of s.nodes)if(['Photo','Video','Photo or video'].includes(q.answer)){const p=questionProofSettings(q),minimum=Math.max(1,q.proofRequiredMin||p.minFiles||1);if(!Array.isArray(p.accepts)||!p.accepts.length||p.accepts.some(a=>!['photo','video'].includes(a)))errors.push(q.label+': choose valid capture types.');if(!Number.isInteger(p.maxFiles)||p.maxFiles<1||!Number.isInteger(minimum)||minimum<1||minimum>p.maxFiles)errors.push(q.label+': proof minimum and maximum are invalid.')}return [...new Set(errors)]};
const proofAnswerEdit=editNode;editNode=function(key,value,refresh){proofAnswerEdit(key,value,refresh);if(key==='answer'&&canEdit()&&['Photo','Video','Photo or video'].includes(value)){const q=sop().nodes.find(n=>n.id===selected);if(q){const p=questionProofSettings(q);p.accepts=value==='Photo'?['photo']:value==='Video'?['video']:['photo','video'];q.proof=p;persist();inspect()}}};
